  function exportCsv(){const h=['#','trade_id','order_id','symbol','provider','timeframe','entry_time','exit_time','side','order_type','requested_entry','actual_entry','exit_price','lots','initial_lots','remaining_lots','sl','tp','spread_points','slippage_points','entry_commission','exit_commission','total_commission','gross_pnl','net_pnl','r_multiple','result','exit_reason','entry_session','exit_session','tag','note'],rows=state.trades.map((t,i)=>[i+1,t.tradeId||'',t.id||'',t.symbol||INSTRUMENT.symbol,t.provider||state.provider||'',t.timeframe||currentTf,t.openedAt?new Date(t.openedAt*1000).toISOString():'',t.closedAt?new Date(t.closedAt*1000).toISOString():'',t.side,t.orderType,t.requestedEntry??'',t.actualEntry??t.entry??'',t.exitPrice??t.exit??'',t.lots,t.initialLots??t.lots,t.remainingLots??0,t.sl??'',t.tp??'',t.spread??'',t.slippage??'',t.entryCommission??0,t.exitCommission??0,t.totalCommission??t.costs??0,t.grossPnL??t.gross??0,t.netPnL??t.net??0,t.RMultiple??t.r??0,t.result||'',t.exitReason||t.reason||'',t.entrySession||'',t.exitSession||'',t.tag||'',t.note||''].map(v=>`"${String(v).replace(/"/g,'""')}"`).join(','));download(new Blob([[h.join(','),...rows].join('\n')],{type:'text/csv'}),'xauusd-backtest-trades.csv')}
  function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
  async function screenshot(){try{const base=chart.takeScreenshot(),r=$('chart').getBoundingClientRect(),out=document.createElement('canvas');out.width=base.width;out.height=base.height;const ctx=out.getContext('2d');ctx.drawImage(base,0,0);const svg=$('drawingOverlay').cloneNode(true),sx=base.width/Math.max(1,r.width),sy=base.height/Math.max(1,r.height),group=document.createElementNS('http://www.w3.org/2000/svg','g');while(svg.firstChild)group.appendChild(svg.firstChild);group.setAttribute('transform',`scale(${sx} ${sy})`);svg.appendChild(group);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('width',base.width);svg.setAttribute('height',base.height);const blob=new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),img=new Image();img.onload=()=>{ctx.drawImage(img,0,0,base.width,base.height);URL.revokeObjectURL(url);out.toBlob(b=>download(b,'xauusd-backtest-chart.png'));toast('Chart screenshot saved with drawings and trade overlays.','success')};img.onerror=()=>{URL.revokeObjectURL(url);toast('Overlay compositing failed.','error')};img.src=url}catch{toast('Screenshot is unavailable in this browser.','error')}}
  function saveSession(){state.isPlaying=false;clearInterval(timer);localStorage.setItem(SAVED_KEY,JSON.stringify({state,drawings}));toast('Session snapshot saved.','success')}
